CREATE TYPE synthetic_enum AS ENUM('synthetic');CREATE SEQUENCE synthetic_ids START 10000;
CREATE TABLE "users"("id" integer DEFAULT nextval('synthetic_ids') NOT NULL,"tenant_id" uuid,"branch_id" uuid,"name" varchar DEFAULT 'synthetic' NOT NULL,"is_working" boolean,"role" varchar,"phone" varchar,"email" varchar DEFAULT 'synthetic' NOT NULL,"password_hash" varchar DEFAULT 'synthetic' NOT NULL,"department_id" integer,"created_at" timestamptz DEFAULT CURRENT_TIMESTAMP,"updated_at" timestamptz,"national_id" varchar,"insurance_no" varchar,"marital_status" varchar,"gender" varchar,"birth_date" date,"job_title_id" integer,"address" text,"salary" numeric,"hire_date" date,"badge_number" varchar,"device_code" varchar);
CREATE TABLE "tenants"("id" uuid DEFAULT gen_random_uuid() NOT NULL,"status" varchar,"template_name" varchar);
CREATE TABLE "branches"("id" uuid DEFAULT gen_random_uuid() NOT NULL,"tenant_id" uuid,"is_main" boolean);
CREATE TABLE "user_branches"("user_id" integer DEFAULT 0 NOT NULL,"branch_id" uuid DEFAULT gen_random_uuid() NOT NULL);
CREATE TABLE "tenant_overrides"("tenant_id" uuid,"modules" jsonb,"limits" jsonb,"notes" text,"updated_at" timestamptz,"id" integer DEFAULT nextval('synthetic_ids') NOT NULL);
CREATE TABLE "domain_events"("id" uuid DEFAULT gen_random_uuid() NOT NULL,"tenant_id" varchar DEFAULT 'synthetic' NOT NULL,"branch_id" varchar,"aggregate_type" varchar DEFAULT 'synthetic' NOT NULL,"aggregate_id" varchar DEFAULT 'synthetic' NOT NULL,"event_name" varchar DEFAULT 'synthetic' NOT NULL,"version" varchar,"payload" jsonb,"actor_id" varchar,"occurred_at" timestamptz);
CREATE TABLE "activities"("id" uuid DEFAULT gen_random_uuid() NOT NULL,"tenant_id" varchar,"user_id" integer,"entity_type" varchar,"entity_id" varchar DEFAULT 'synthetic' NOT NULL,"action" varchar,"meta" jsonb,"created_at" timestamptz DEFAULT CURRENT_TIMESTAMP,"scheduled_at" timestamptz,"reminder_note" text,"reminder_sent_at" timestamptz,"is_reminder_dismissed" boolean,"branch_id" varchar,"activity_type" varchar,"actor_id" varchar,"actor_name" varchar,"title" varchar,"details" jsonb,"visibility" varchar);
CREATE TABLE "outbox_events"("id" uuid DEFAULT gen_random_uuid() NOT NULL,"tenant_id" varchar DEFAULT 'synthetic' NOT NULL,"branch_id" varchar,"aggregate_type" varchar DEFAULT 'synthetic' NOT NULL,"aggregate_id" varchar DEFAULT 'synthetic' NOT NULL,"event_name" varchar DEFAULT 'synthetic' NOT NULL,"version" varchar,"payload" jsonb,"actor_id" varchar,"created_at" timestamptz DEFAULT CURRENT_TIMESTAMP,"status" varchar,"processed_at" timestamptz,"retry_count" integer);
CREATE TABLE "system_notifications"("id" integer DEFAULT nextval('synthetic_ids') NOT NULL,"tenant_id" uuid,"branch_id" uuid,"user_id" integer,"type" varchar DEFAULT 'synthetic' NOT NULL,"title" varchar DEFAULT 'synthetic' NOT NULL,"message" text,"link" varchar,"metadata" jsonb,"is_read" boolean,"created_at" timestamptz DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "customers"("id" integer DEFAULT nextval('synthetic_ids') NOT NULL,"name" varchar DEFAULT 'synthetic' NOT NULL,"phone" varchar,"branch_id" uuid DEFAULT gen_random_uuid() NOT NULL,"company_name" varchar,"email" varchar,"address" text,"source" varchar,"assigned_to" integer,"status" varchar,"created_at" timestamptz DEFAULT CURRENT_TIMESTAMP,"updated_at" timestamptz,"source_id" integer,"manager_id" integer,"tenant_id" uuid,"entity_type" varchar,"budget_min" numeric,"budget_max" numeric,"preferred_area_min" numeric,"preferred_area_max" numeric,"preferred_location" text,"preferred_rooms" integer,"tax_no" varchar,"reg_no" varchar,"is_active" boolean,"is_blacklisted" boolean,"meta_lead_id" varchar,"notes" text,"meta_form_name" varchar,"meta_form_id" varchar,"classification_id" integer,"classification_name" varchar,"area_id" integer,"area_name" varchar,"whatsapp_welcome_sent" boolean,"whatsapp_welcome_sent_at" timestamptz,"meta_campaign_name" varchar,"meta_adset_name" varchar,"meta_ad_name" varchar);
CREATE TABLE "deals"("id" integer DEFAULT nextval('synthetic_ids') NOT NULL,"title" varchar DEFAULT 'synthetic' NOT NULL,"branch_id" uuid DEFAULT gen_random_uuid() NOT NULL,"tenant_id" uuid,"assigned_to" integer,"value" numeric,"pipeline_stage" varchar,"client_id" integer,"project_id" integer,"created_at" timestamptz DEFAULT CURRENT_TIMESTAMP,"updated_at" timestamptz,"product_id" integer,"custom_fields" jsonb,"unit_id" varchar,"probability" integer,"expected_close_date" date,"next_action" varchar,"source_type" varchar,"source_id" varchar);
CREATE TABLE "re_contracts"("id" uuid DEFAULT gen_random_uuid() NOT NULL,"contract_number" varchar DEFAULT 'synthetic' NOT NULL,"deal_id" integer DEFAULT 0 NOT NULL,"tenant_id" varchar DEFAULT 'synthetic' NOT NULL,"branch_id" varchar,"end_date" date,"status" varchar DEFAULT 'synthetic' NOT NULL,"expiry_reminder_sent_at" timestamp,"expired_notified_at" timestamp,"customer_id" integer,"unit_id" varchar,"contract_date" date DEFAULT CURRENT_DATE NOT NULL,"contract_value" numeric DEFAULT 0 NOT NULL,"down_payment" numeric DEFAULT 0 NOT NULL,"remaining_amount" numeric DEFAULT 0 NOT NULL,"notes" text,"created_by" varchar,"created_at" timestamp DEFAULT CURRENT_TIMESTAMP,"updated_at" timestamp,"start_date" date,"duration_months" integer);
CREATE TABLE "notification_jobs"("id" uuid DEFAULT gen_random_uuid() NOT NULL,"tenant_id" uuid DEFAULT gen_random_uuid() NOT NULL,"branch_id" uuid,"event_name" varchar DEFAULT 'synthetic' NOT NULL,"channel" varchar DEFAULT 'synthetic' NOT NULL,"recipient_type" varchar DEFAULT 'synthetic' NOT NULL,"recipient_id" varchar,"recipient_phone" varchar DEFAULT 'synthetic' NOT NULL,"recipient_name" varchar,"payload" jsonb DEFAULT '{}' NOT NULL,"deduplication_key" varchar,"status" varchar DEFAULT 'synthetic' NOT NULL,"priority" integer DEFAULT 0 NOT NULL,"attempts" integer DEFAULT 0 NOT NULL,"max_attempts" integer DEFAULT 0 NOT NULL,"scheduled_at" timestamptz,"processed_at" timestamptz,"error_message" text,"meta_message_id" varchar,"created_at" timestamptz DEFAULT CURRENT_TIMESTAMP,"updated_at" timestamptz);
CREATE TABLE "notification_logs"("id" uuid DEFAULT gen_random_uuid() NOT NULL,"job_id" uuid,"tenant_id" uuid DEFAULT gen_random_uuid() NOT NULL,"branch_id" uuid,"channel" varchar DEFAULT 'synthetic' NOT NULL,"event_name" varchar DEFAULT 'synthetic' NOT NULL,"recipient_type" varchar DEFAULT 'synthetic' NOT NULL,"recipient_id" varchar,"recipient_phone" varchar DEFAULT 'synthetic' NOT NULL,"recipient_name" varchar,"message_body" text,"template_name" varchar,"meta_message_id" varchar,"delivery_status" varchar DEFAULT 'synthetic' NOT NULL,"error_code" varchar,"error_message" text,"sent_at" timestamptz,"delivered_at" timestamptz,"read_at" timestamptz,"failed_at" timestamptz,"metadata" jsonb,"created_at" timestamptz DEFAULT CURRENT_TIMESTAMP,"updated_at" timestamptz);
CREATE TABLE "notification_rules"("id" integer DEFAULT nextval('synthetic_ids') NOT NULL,"tenant_id" uuid DEFAULT gen_random_uuid() NOT NULL,"branch_id" uuid,"event_name" varchar DEFAULT 'synthetic' NOT NULL,"is_enabled" boolean DEFAULT false NOT NULL,"channels" jsonb DEFAULT '{}' NOT NULL,"template_name" varchar,"template_language" varchar DEFAULT 'synthetic' NOT NULL,"recipient_roles" jsonb,"conditions" jsonb,"created_at" timestamptz DEFAULT CURRENT_TIMESTAMP,"updated_at" timestamptz);
CREATE TABLE "re_units"("id" uuid DEFAULT gen_random_uuid() NOT NULL,"name" varchar DEFAULT 'synthetic' NOT NULL,"project_name" varchar,"unit_number" varchar,"type" varchar,"floor" varchar,"area_sqm" varchar,"price" numeric,"status" varchar,"tenant_id" varchar,"branch_id" varchar,"vendor_id" varchar,"responsible_person_id" varchar,"transaction_type" varchar,"rooms" integer,"location" text,"created_at" timestamp DEFAULT CURRENT_TIMESTAMP,"updated_at" timestamp,"reservation_expires_at" timestamp,"assigned_to" varchar,"developer_id" uuid,"project_id" uuid,"phase_id" uuid,"building_id" uuid,"reservation_extended_at" timestamp,"reservation_extended_by" varchar,"reservation_extension_count" integer);
CREATE TABLE "system_logs"("id" integer DEFAULT nextval('synthetic_ids') NOT NULL,"user_id" integer,"action" varchar DEFAULT 'synthetic' NOT NULL,"entity_type" varchar DEFAULT 'synthetic' NOT NULL,"entity_id" integer,"details" jsonb,"created_at" timestamptz DEFAULT CURRENT_TIMESTAMP,"tenant_id" uuid,"ip_address" varchar,"user_agent" text,"level" varchar,"branch_id" varchar);
CREATE TABLE "task_statuses"("id" integer DEFAULT nextval('synthetic_ids') NOT NULL,"name" varchar DEFAULT 'synthetic' NOT NULL,"color" varchar,"order_index" integer,"can_make_deal" boolean,"is_final" boolean,"tenant_id" varchar DEFAULT 'synthetic' NOT NULL,"created_at" timestamp DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "tasks"("id" integer DEFAULT nextval('synthetic_ids') NOT NULL,"title" varchar DEFAULT 'synthetic' NOT NULL,"description" text,"priority" varchar,"status" varchar,"assigned_to" integer,"parent_type" varchar,"parent_id" varchar,"due_date" timestamptz,"created_at" timestamptz DEFAULT CURRENT_TIMESTAMP,"updated_at" timestamptz,"director_id" integer,"created_by" integer,"tenant_id" uuid,"branch_id" uuid DEFAULT gen_random_uuid() NOT NULL,"status_id" integer,"can_make_deal" boolean);
CREATE TABLE "whatsapp_settings"("tenant_id" uuid DEFAULT gen_random_uuid() NOT NULL,"phone_number_id" varchar DEFAULT 'synthetic' NOT NULL,"access_token" text DEFAULT 'synthetic' NOT NULL,"template_name" varchar DEFAULT 'synthetic' NOT NULL,"template_language_ar" varchar DEFAULT 'synthetic' NOT NULL,"template_language_en" varchar DEFAULT 'synthetic' NOT NULL,"send_arabic" boolean DEFAULT false NOT NULL,"send_english" boolean DEFAULT false NOT NULL,"default_country_code" varchar DEFAULT 'synthetic' NOT NULL,"is_active" boolean DEFAULT false NOT NULL,"created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,"updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,"waba_id" varchar,"meta_app_secret" text,"meta_webhook_verify_token" text,"auto_greeting_enabled" boolean,"auto_greeting_triggers" text[],"auto_greeting_template" varchar,"auto_greeting_language" varchar,"variable_mapping" jsonb,"connection_type" varchar DEFAULT 'synthetic' NOT NULL,"coexistence_status" varchar,"coexistence_metadata" jsonb);
CREATE TABLE "purchase_invoices"("warehouse_id" integer);
CREATE TABLE "purchase_orders"("warehouse_id" integer DEFAULT 0 NOT NULL);
CREATE TABLE "purchase_requests"("warehouse_id" integer);
CREATE TABLE "stock_movements"("id" integer DEFAULT nextval('synthetic_ids') NOT NULL,"from_warehouse_id" integer,"to_warehouse_id" integer);
CREATE TABLE "warehouse_keepers"("id" integer DEFAULT nextval('synthetic_ids') NOT NULL,"warehouse_id" integer,"user_id" integer,"tenant_id" uuid);
CREATE TABLE "warehouses"("id" integer DEFAULT nextval('synthetic_ids') NOT NULL,"tenant_id" uuid,"branch_id" uuid,"is_active" boolean);
ALTER TABLE "branches" ADD CONSTRAINT "branches_pkey" PRIMARY KEY (id);
ALTER TABLE "tenant_overrides" ADD CONSTRAINT "tenant_overrides_pkey" PRIMARY KEY (id);
ALTER TABLE "tenants" ADD CONSTRAINT "tenants_pkey" PRIMARY KEY (id);
ALTER TABLE "user_branches" ADD CONSTRAINT "user_branches_pkey" PRIMARY KEY (user_id, branch_id);
