ALTER TABLE "notification_jobs" ADD CONSTRAINT "notification_jobs_pkey" PRIMARY KEY (id);
ALTER TABLE "notification_logs" ADD CONSTRAINT "notification_logs_pkey" PRIMARY KEY (id);
ALTER TABLE "notification_rules" ADD CONSTRAINT "notification_rules_pkey" PRIMARY KEY (id);
ALTER TABLE "re_units" ADD CONSTRAINT "re_units_pkey" PRIMARY KEY (id);
ALTER TABLE "system_logs" ADD CONSTRAINT "system_logs_pkey" PRIMARY KEY (id);
ALTER TABLE "tasks" ADD CONSTRAINT "tasks_pkey" PRIMARY KEY (id);
ALTER TABLE "task_statuses" ADD CONSTRAINT "task_statuses_pkey" PRIMARY KEY (id);
ALTER TABLE "whatsapp_settings" ADD CONSTRAINT "whatsapp_settings_pkey" PRIMARY KEY (tenant_id);
ALTER TABLE "warehouse_keepers" ADD CONSTRAINT "warehouse_keepers_pkey" PRIMARY KEY (id);
ALTER TABLE "warehouse_keepers" ADD CONSTRAINT "warehouse_keepers_warehouse_id_user_id_key" UNIQUE (warehouse_id, user_id);
ALTER TABLE "warehouses" ADD CONSTRAINT "warehouses_pkey" PRIMARY KEY (id);
ALTER TABLE "purchase_invoices" ADD CONSTRAINT "purchase_invoices_warehouse_id_fkey" FOREIGN KEY (warehouse_id) REFERENCES warehouses(id) ON DELETE RESTRICT;
ALTER TABLE "purchase_orders" ADD CONSTRAINT "purchase_orders_warehouse_id_fkey" FOREIGN KEY (warehouse_id) REFERENCES warehouses(id) ON DELETE RESTRICT;
ALTER TABLE "purchase_requests" ADD CONSTRAINT "purchase_requests_warehouse_id_fkey" FOREIGN KEY (warehouse_id) REFERENCES warehouses(id) ON DELETE SET NULL;
ALTER TABLE "stock_movements" ADD CONSTRAINT "stock_movements_from_warehouse_id_fkey" FOREIGN KEY (from_warehouse_id) REFERENCES warehouses(id) ON DELETE RESTRICT;
ALTER TABLE "stock_movements" ADD CONSTRAINT "stock_movements_to_warehouse_id_fkey" FOREIGN KEY (to_warehouse_id) REFERENCES warehouses(id) ON DELETE RESTRICT;
ALTER TABLE "warehouse_keepers" ADD CONSTRAINT "warehouse_keepers_warehouse_id_fkey" FOREIGN KEY (warehouse_id) REFERENCES warehouses(id) ON DELETE CASCADE;
CREATE INDEX idx_activities_due_reminders ON public.activities USING btree (scheduled_at) WHERE ((scheduled_at IS NOT NULL) AND (reminder_sent_at IS NULL) AND (is_reminder_dismissed = false));
CREATE UNIQUE INDEX idx_notif_jobs_dedup ON public.notification_jobs USING btree (tenant_id, deduplication_key) WHERE ((deduplication_key IS NOT NULL) AND ((status)::text = ANY ((ARRAY['pending'::character varying, 'processing'::character varying, 'completed'::character varying])::text[])));
